package com.studentmanagement.dao;

import com.studentmanagement.model.Student;
import com.studentmanagement.util.DBConnection;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Map;

public class StudentDAO {

    /**
     * Adds a student to the database and returns the generated student ID.
     *
     * @param student the student details to save
     * @return the ID generated by the database
     * @throws SQLException if the student cannot be saved or its ID cannot be retrieved
     */
    public int addStudent(Student student) throws SQLException {
        String sql = "INSERT INTO students (name, age, gender, course, email, phone, address, marks) "
                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?)";

        // Try-with-resources closes the connection and statement after the insert.
        try (Connection connection = DBConnection.getConnection();
             PreparedStatement statement = connection.prepareStatement(
                     sql, Statement.RETURN_GENERATED_KEYS)) {
            // Fill each placeholder with the matching value from the Student object.
            statement.setString(1, student.getName());
            statement.setInt(2, student.getAge());
            statement.setString(3, student.getGender());
            statement.setString(4, student.getCourse());
            statement.setString(5, student.getEmail());
            statement.setString(6, student.getPhone());
            statement.setString(7, student.getAddress());
            statement.setBigDecimal(8, student.getMarks());

            statement.executeUpdate();

            // MySQL returns the auto-generated student_id through the generated keys result.
            try (ResultSet generatedKeys = statement.getGeneratedKeys()) {
                if (generatedKeys.next()) {
                    return generatedKeys.getInt(1);
                }
                throw new SQLException("Adding the student succeeded, but no generated ID was returned.");
            }
        }
    }

    /**
     * Retrieves all students from the database.
     *
     * @return a list containing all student records
     * @throws SQLException if the records cannot be retrieved
     */
    public ArrayList<Student> getAllStudents() throws SQLException {
        ArrayList<Student> students = new ArrayList<>();
        String sql = "SELECT student_id, name, age, gender, course, email, phone, address, marks "
                + "FROM students";

        // Try-with-resources closes the connection, statement, and result set.
        try (Connection connection = DBConnection.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql);
             ResultSet resultSet = statement.executeQuery()) {
            while (resultSet.next()) {
                // Match the database columns to the Student constructor parameter order.
                Student student = new Student(
                        resultSet.getInt("student_id"),
                        resultSet.getString("name"),
                        resultSet.getInt("age"),
                        resultSet.getString("gender"),
                        resultSet.getString("course"),
                        resultSet.getString("email"),
                        resultSet.getString("phone"),
                        resultSet.getString("address"),
                        resultSet.getBigDecimal("marks")
                );
                students.add(student);
            }
        }

        return students;
    }

    /**
     * Retrieves one student by ID.
     *
     * @param studentId the ID of the student to retrieve
     * @return the matching student, or null if no student has that ID
     * @throws SQLException if the student cannot be retrieved
     */
    public Student getStudentById(int studentId) throws SQLException {
        String sql = "SELECT student_id, name, age, gender, course, email, phone, address, marks "
                + "FROM students WHERE student_id = ?";

        try (Connection connection = DBConnection.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setInt(1, studentId);

            try (ResultSet resultSet = statement.executeQuery()) {
                if (resultSet.next()) {
                    return new Student(
                            resultSet.getInt("student_id"),
                            resultSet.getString("name"),
                            resultSet.getInt("age"),
                            resultSet.getString("gender"),
                            resultSet.getString("course"),
                            resultSet.getString("email"),
                            resultSet.getString("phone"),
                            resultSet.getString("address"),
                            resultSet.getBigDecimal("marks")
                    );
                }
            }
        }

        return null;
    }

    /**
     * Updates the details of an existing student.
     *
     * @param student the student details, including the ID to match
     * @return true if at least one row was updated; otherwise, false
     * @throws SQLException if the update fails
     */
    public boolean updateStudent(Student student) throws SQLException {
        String sql = "UPDATE students SET name = ?, age = ?, gender = ?, course = ?, "
                + "email = ?, phone = ?, address = ?, marks = ? WHERE student_id = ?";

        try (Connection connection = DBConnection.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, student.getName());
            statement.setInt(2, student.getAge());
            statement.setString(3, student.getGender());
            statement.setString(4, student.getCourse());
            statement.setString(5, student.getEmail());
            statement.setString(6, student.getPhone());
            statement.setString(7, student.getAddress());
            statement.setBigDecimal(8, student.getMarks());
            statement.setInt(9, student.getStudentId());

            return statement.executeUpdate() > 0;
        }
    }

    /**
     * Deletes a student by ID.
     *
     * @param studentId the ID of the student to delete
     * @return true if a student was deleted; otherwise, false
     * @throws SQLException if the delete operation fails
     */
    public boolean deleteStudent(int studentId) throws SQLException {
        String sql = "DELETE FROM students WHERE student_id = ?";

        try (Connection connection = DBConnection.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setInt(1, studentId);
            return statement.executeUpdate() > 0;
        }
    }

    /**
     * Retrieves summary statistics for the students table.
     *
     * @return the student count, course count, and marks statistics
     * @throws SQLException if the statistics cannot be retrieved
     */
    public Map<String, Object> getStatistics() throws SQLException {
        String sql = "SELECT COUNT(*) AS totalStudents, "
                + "COUNT(DISTINCT course) AS totalCourses, "
                + "COALESCE(AVG(marks), 0) AS averageMarks, "
                + "COALESCE(MAX(marks), 0) AS highestMarks, "
                + "COALESCE(MIN(marks), 0) AS lowestMarks "
                + "FROM students";
        Map<String, Object> statistics = new LinkedHashMap<>();

        try (Connection connection = DBConnection.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql);
             ResultSet resultSet = statement.executeQuery()) {
            if (resultSet.next()) {
                statistics.put("totalStudents", resultSet.getLong("totalStudents"));
                statistics.put("totalCourses", resultSet.getLong("totalCourses"));
                statistics.put("averageMarks", resultSet.getDouble("averageMarks"));
                statistics.put("highestMarks", resultSet.getDouble("highestMarks"));
                statistics.put("lowestMarks", resultSet.getDouble("lowestMarks"));
            }
        }

        return statistics;
    }
}
